const defaults = {name:'Mori', prompt:'Warm, curious, thoughtful, and gently playful. Keep replies natural and not too long.',look:'moss',endpoint:'',model:'',speak:false};
let config = {...defaults, ...safeParse(localStorage.getItem('mori-preferences'))};
let history = [], activeImage = null, mediaStream = null, mediaKind = '', toastTimer;
function safeParse(v){try{return JSON.parse(v)||{}}catch{return {}}}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
function setMood(mood,label){pet.classList.remove('happy','thinking','talking','sad','angry');if(mood)pet.classList.add(mood);$('#moodLabel').textContent=label}
function happy(){pet.classList.remove('dancing');pet.classList.add('happy');setTimeout(()=>pet.classList.remove('happy'),1200)}
function setName(name){const n=name||'Mori';$('#stageName').textContent=n.toUpperCase();$('#chatName').textContent=n;$('#messageInput').placeholder=`Say something to ${n}…`;document.title=`${n.toLowerCase()} — your little corner of the internet`}
function applyLook(look){document.body.classList.remove('look-lilac','look-peach','look-ocean','look-night');if(look!=='moss')document.body.classList.add(`look-${look}`);$$('.swatch').forEach(b=>b.classList.toggle('selected',b.dataset.look===look))}
function addMessage(text,role='pet',image=null){const row=document.createElement('article');row.className=`message ${role==='user'?'user-message':'pet-message'}`;const avatar=role==='user'?'Y':'✳';const imageMarkup=image?`<img class="attached-image" src="${image}" alt="Shared snapshot" />`:'';row.innerHTML=`<div class="message-avatar">${avatar}</div><div><div class="bubble">${imageMarkup}${escapeHTML(text).replace(/\n/g,'<br>')}</div><div class="message-time">just now</div></div>`;messagesEl.append(row);messagesEl.scrollTop=messagesEl.scrollHeight;$('#suggestions')?.remove();return row}
function showTyping(){const row=document.createElement('article');row.className='message pet-message';row.id='typingMessage';row.innerHTML='<div class="message-avatar">✳</div><div class="bubble typing-indicator"><i></i><i></i><i></i></div>';messagesEl.append(row);messagesEl.scrollTop=messagesEl.scrollHeight;return row}
function detectMood(text){const t=text.toLowerCase();if(/\b(angry|mad|furious|hate this)\b/.test(t)){setMood('angry','a little fired up');return}if(/\b(sad|lonely|miss|rough day|hurt)\b/.test(t)){setMood('sad','here for you');return}if(/\b(thank|love|yay|excited|great|happy|haha)\b/.test(t)){setMood('happy','feeling sunny');return}setMood('thinking','thinking gently…')}
function moodFromReply(text){const t=text.toLowerCase();if(/\b(sorry|hard|tough|sad|grief|lonely)\b/.test(t))setMood('sad','here for you');else if(/\b(wow|yay|lovely|excited|wonderful)\b/.test(t))setMood('happy','feeling sunny');else setMood('', 'feeling mellow')}
function systemPrompt(){const style=config.prompt.trim()||defaults.prompt;return `You are ${config.name}, a friendly, fictional desktop companion. Personality and style: ${style}\nBe honest about limitations; do not claim to perceive the user or device unless the user explicitly shares an image in this message. Be respectful and supportive. Follow the connected AI provider's policies and safety requirements; do not help with harmful wrongdoing or exploitative content. You may discuss difficult topics in a safe, non-instructional way. Keep a conversational tone.`}
async function requestAI(text,image){const key=sessionStorage.getItem('mori-api-key')||'';const base=config.endpoint.trim().replace(/\/+$/,'');if(!base||!config.model||!key)return demoReply(text,image);const content=image?[{type:'text',text:text||'Please describe what is in this image.'},{type:'image_url',image_url:{url:image}}]:text;const body={model:config.model,messages:[{role:'system',content:systemPrompt()},...history.slice(-14),{role:'user',content}]};const response=await fetch(`${base}/chat/completions`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify(body)});if(!response.ok){let detail='';try{detail=(await response.json()).error?.message||''}catch{}throw new Error(detail||`Provider returned ${response.status}`)}const data=await response.json();return data.choices?.[0]?.message?.content||'I didn’t get a reply that time. Want to try again?'}
function demoReply(text,image){const q=text.toLowerCase();if(image)return `I can see the snapshot you shared${q?` — you asked: “${text}”`:''}. This demo companion doesn’t have a connected vision model yet. Add your own vision-capable API in settings and I can help interpret it.`;if(/story/.test(q))return 'Once, a tiny moss spirit found a moonbeam caught in a teacup. It carried the light home very carefully, stopping every few steps to make sure the stars were still there. ☾';if(/think|help|decision|feel|mind/.test(q))return 'I’m listening. Want to tell me a little more about what’s going on? We can untangle it one small thread at a time.';if(/make|create|build|today/.test(q))return 'Let’s make something small and lovely. We could dream up a cozy room, invent a tiny creature, or plan a five-minute creative break. What sounds nice?';if(/hello|hi\b|hey/.test(q))return 'Hey there! I’m happy to keep you company. How has your day been treating you?';return `That’s a thoughtful thing to bring here. ${text.length>100?'There are a few threads in what you wrote, and we can take them one at a time.':'I’m here to explore it with you.'} Want to tell me what part matters most right now?`}
async function sendMessage(text,image=null){text=text.trim();if(!text&&!image)return;$('#petStatus').textContent='Listening';detectMood(text);addMessage(text||'What do you notice?', 'user',image);const typing=showTyping();input.value='';input.style.height='auto';$('#petStatus').textContent='Thinking';try{const answer=await requestAI(text,image);typing.remove();addMessage(typeof answer==='string'?answer:answer.map?.(x=>x.text||'').join('')||'I’m here.');history.push({role:'user',content:text||'What do you notice?'},{role:'assistant',content:typeof answer==='string'?answer:'I’m here.'});history=history.slice(-20);moodFromReply(typeof answer==='string'?answer:'');if(config.speak)speak(typeof answer==='string'?answer:'I’m here.')}catch(err){typing.remove();addMessage(`I couldn’t reach that AI endpoint. ${err.message}. Check your connection settings, or chat with me in demo mode.`);setMood('', 'waiting patiently');setToast('Could not connect to your provider')}finally{$('#petStatus').textContent='Here with you';activeImage=null;}}
function speak(text){if(!('speechSynthesis'in window)){setToast('Speech synthesis is not available in this browser');return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);const selected=$('#voiceSelect').value;if(selected){const voice=speechSynthesis.getVoices().find(v=>v.name===selected);if(voice)utterance.voice=voice}utterance.rate=.96;utterance.pitch=1.07;utterance.onstart=()=>{pet.classList.add('talking');$('#petStatus').textContent='Speaking'};utterance.onend=()=>{pet.classList.remove('talking');$('#petStatus').textContent='Here with you'};speechSynthesis.speak(utterance)}
function populateVoices(){if(!('speechSynthesis'in window))return;const previous=config.voice||'';const voices=speechSynthesis.getVoices();$('#voiceSelect').innerHTML='<option value="">System default</option>'+voices.map(v=>`<option value="${escapeHTML(v.name)}">${escapeHTML(v.name)}${v.lang?` · ${escapeHTML(v.lang)}`:''}</option>`).join('');$('#voiceSelect').value=previous}
if('speechSynthesis'in window){populateVoices();speechSynthesis.onvoiceschanged=populateVoices}
$('#chatForm').addEventListener('submit',e=>{e.preventDefault();sendMessage(input.value,activeImage)});
input.addEventListener('input',()=>{input.style.height='auto';input.style.height=`${Math.min(input.scrollHeight,105)}px`});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chatForm').requestSubmit()}});
messagesEl.addEventListener('click',e=>{const b=e.target.closest('.suggestion');if(b){input.value=b.textContent;$('#chatForm').requestSubmit()}});
$('#petWrap').addEventListener('click',happy);$('#petWrap').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();happy()}});$('#petWave').addEventListener('click',()=>{happy();setToast(`${config.name} gives a happy little wiggle`)});$('#danceButton').addEventListener('click',()=>{pet.classList.add('dancing');setMood('','grooving softly');setTimeout(()=>{pet.classList.remove('dancing');setMood('','feeling mellow')},4000)});$('#randomMood').addEventListener('click',()=>{const moods=[['happy','feeling sunny'],['thinking','curious today'],['','feeling mellow']];const [m,l]=moods[Math.floor(Math.random()*moods.length)];setMood(m,l);happy()});
function openSettings(tab='identity'){$('#settingsModal').hidden=false;$('#nameField').value=config.name;$('#promptField').value=config.prompt;$('#endpointField').value=config.endpoint;$('#modelField').value=config.model;$('#keyField').value=sessionStorage.getItem('mori-api-key')||'';$('#speakToggle').checked=config.speak;$('#voiceSelect').value=config.voice||'';applyLook(config.look);switchSettingsTab(tab)}function closeSettings(){$('#settingsModal').hidden=true}
function switchSettingsTab(tab){$$('.setting-tab').forEach(b=>b.classList.toggle('selected',b.dataset.settingsTab===tab));$$('[data-settings-panel]').forEach(p=>p.hidden=p.dataset.settingsPanel!==tab)}
$('#settingsButton').addEventListener('click',()=>openSettings());$('#openSettingsFoot').addEventListener('click',()=>openSettings());$$('[data-close]').forEach(b=>b.addEventListener('click',closeSettings));$('#settingsModal').addEventListener('click',e=>{if(e.target===$('#settingsModal'))closeSettings()});$$('.setting-tab').forEach(b=>b.addEventListener('click',()=>switchSettingsTab(b.dataset.settingsTab)));$$('.swatch').forEach(b=>b.addEventListener('click',()=>applyLook(b.dataset.look)));
$('#saveSettings').addEventListener('click',()=>{config={...config,name:$('#nameField').value.trim()||'Mori',prompt:$('#promptField').value,endpoint:$('#endpointField').value.trim(),model:$('#modelField').value.trim(),look:$('.swatch.selected')?.dataset.look||'moss',speak:$('#speakToggle').checked,voice:$('#voiceSelect').value};localStorage.setItem('mori-preferences',JSON.stringify(config));const key=$('#keyField').value.trim();if(key)sessionStorage.setItem('mori-api-key',key);else sessionStorage.removeItem('mori-api-key');setName(config.name);applyLook(config.look);closeSettings();$('#connectionStatus').textContent=config.endpoint&&config.model&&key?'CONNECTED BY YOU':'YOUR QUIET CORNER';setToast('Your companion settings are saved')});
$('#testConnection').addEventListener('click',async()=>{const note=$('#connectionNote'),base=$('#endpointField').value.trim().replace(/\/+$/,''),key=$('#keyField').value.trim(),model=$('#modelField').value.trim();if(!base||!key||!model){note.textContent='Add a base URL, model, and API key to test.';return}note.textContent='Testing your connection…';try{const r=await fetch(`${base}/chat/completions`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify({model,messages:[{role:'user',content:'Reply with the word ready.'}],max_tokens:10})});if(!r.ok)throw Error(`HTTP ${r.status}`);note.textContent='Connection looks good!';}catch(e){note.textContent=`Could not test: ${e.message}. Check URL, CORS, and credentials.`}});
$('#clearChat').addEventListener('click',()=>{history=[];messagesEl.innerHTML='<div class="day-divider"><span>FRESH START</span></div>';setMood('','feeling mellow');addMessage('A fresh page. What would you like to talk about?');setToast('Conversation cleared')});$('#resetData').addEventListener('click',()=>{localStorage.removeItem('mori-preferences');sessionStorage.removeItem('mori-api-key');location.reload()});
function searchWeb(){const term=input.value.trim()||prompt('What would you like to search for?');if(term)window.open(`https://duckduckgo.com/?q=${encodeURIComponent(term)}`,'_blank','noopener,noreferrer')}
$('#searchButton').addEventListener('click',searchWeb);$('#chatSearch').addEventListener('click',searchWeb);
let recognition=null;$('#voiceButton').addEventListener('click',()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){setToast('Voice input is not supported in this browser');return}if(recognition){recognition.stop();recognition=null;$('#voiceButton').classList.remove('listening');return}recognition=new SR();recognition.lang=navigator.language||'en-US';recognition.interimResults=false;recognition.onresult=e=>{input.value=e.results[0][0].transcript;input.focus()};recognition.onerror=e=>setToast(`Voice input: ${e.error}`);recognition.onend=()=>{$('#voiceButton').classList.remove('listening');recognition=null};recognition.start();$('#voiceButton').classList.add('listening');setToast('Listening — tap Voice when you’re done')});
const mediaModal=$('#mediaModal'),video=$('#mediaVideo');function closeMedia(){mediaModal.hidden=true;if(mediaStream){mediaStream.getTracks().forEach(t=>t.stop());mediaStream=null}video.srcObject=null}
async function startMedia(kind){mediaKind=kind;$('#mediaTitle').textContent=kind==='screen'?'Share a screen snapshot':'Take a camera snapshot';$('#mediaEyebrow').textContent=kind==='screen'?'ONE STILL IMAGE ONLY':'CAMERA OFF UNTIL YOU ASK';$('#mediaDescription').textContent=kind==='screen'?'Choose a screen, window, or tab. Mori only receives a still image after you confirm.':'Your camera preview stays here. Mori only receives a still image after you confirm.';mediaModal.hidden=false;try{mediaStream=kind==='screen'?await navigator.mediaDevices.getDisplayMedia({video:{frameRate:5},audio:false}):await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});video.srcObject=mediaStream;await video.play()}catch(e){closeMedia();setToast(e.name==='NotAllowedError'?'Permission was not granted. Nothing was shared.':`Could not open ${kind}: ${e.message}`)}}
$('#screenButton').addEventListener('click',()=>startMedia('screen'));$('#cameraButton').addEventListener('click',()=>startMedia('camera'));$$('[data-media-close]').forEach(b=>b.addEventListener('click',closeMedia));mediaModal.addEventListener('click',e=>{if(e.target===mediaModal)closeMedia()});$('#captureMedia').addEventListener('click',()=>{if(!video.videoWidth){setToast('The preview is not ready yet');return}const canvas=document.createElement('canvas'),scale=Math.min(1,1000/video.videoWidth);canvas.width=video.videoWidth*scale;canvas.height=video.videoHeight*scale;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);activeImage=canvas.toDataURL('image/jpeg',.78);closeMedia();input.focus();setToast('Snapshot attached — add a message or press send');});
